<template><div class="page"><div class="page-title"><h2>用户管理</h2><el-button type="primary" @click="create">新增用户</el-button></div><div class="panel"><el-table :data="rows" stripe><el-table-column prop="username" label="用户名" /><el-table-column prop="realName" label="姓名" /><el-table-column prop="role" label="角色" /><el-table-column prop="enabled" label="启用"><template #default="{row}"><el-switch v-model="row.enabled" disabled /></template></el-table-column><el-table-column label="操作"><template #default="{row}"><el-button link @click="edit(row)">编辑</el-button><el-button link type="danger" @click="remove(row)">删除</el-button></template></el-table-column></el-table></div><el-dialog v-model="dialog" :title="form.id?'编辑用户':'新增用户'"><el-form label-width="90px"><el-form-item label="用户名"><el-input v-model="form.username" :disabled="!!form.id" /></el-form-item><el-form-item label="姓名"><el-input v-model="form.realName" /></el-form-item><el-form-item label="角色"><el-select v-model="form.role"><el-option label="管理员" value="ADMIN" /><el-option label="计划员" value="PLANNER" /><el-option label="只读" value="VIEWER" /></el-select></el-form-item><el-form-item label="密码"><el-input v-model="form.password" type="password" /></el-form-item></el-form><template #footer><el-button @click="dialog=false">取消</el-button><el-button type="primary" @click="save">保存</el-button></template></el-dialog></div></template>
<script setup>
import { reactive, ref } from 'vue'; import { systemApi } from '../api'; import { ElMessage } from 'element-plus'
const rows=ref([]),dialog=ref(false),form=reactive({});async function load(){rows.value=await systemApi.users()};function create(){Object.assign(form,{id:null,username:'',realName:'',role:'PLANNER',password:'',enabled:true});dialog.value=true};function edit(row){Object.assign(form,{...row,password:''});dialog.value=true};async function save(){if(form.id)await systemApi.updateUser(form.id,form);else await systemApi.createUser(form);dialog.value=false;load()};async function remove(row){await systemApi.deleteUser(row.id);ElMessage.success('已删除');load()};load()
</script>
